SET search_path TO public;

CREATE TABLE "access_group_admission_receipt" (
	"operation_id" uuid PRIMARY KEY,
	"group_id" uuid NOT NULL,
	"review_id" uuid NOT NULL,
	"proposal_digest" text NOT NULL,
	"effect_digest" text NOT NULL,
	"approval_ids" jsonb NOT NULL,
	"recovery_path_ids" jsonb NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "access_group_admission_receipt_budget_check" CHECK (jsonb_array_length("approval_ids") between 1 and 64 and jsonb_array_length("recovery_path_ids") between 1 and 64)
);

CREATE TABLE "access_group_approval" (
	"id" uuid PRIMARY KEY,
	"review_id" uuid NOT NULL,
	"principal_id" uuid NOT NULL,
	"subject_id" uuid NOT NULL,
	"proof" jsonb NOT NULL,
	"selection" jsonb NOT NULL,
	"proposal_digest" text NOT NULL,
	"effect_digest" text NOT NULL,
	"source_digest" text NOT NULL,
	"witness_digest" text NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"valid_until" timestamp(3) with time zone NOT NULL,
	"revoked_at" timestamp(3) with time zone,
	"revoke_operation_id" uuid,
	CONSTRAINT "access_group_approval_time_check" CHECK (isfinite("valid_until") and "valid_until">"created_at" and ("revoked_at" is null)=("revoke_operation_id" is null)),
	CONSTRAINT "access_group_approval_digest_check" CHECK ("proposal_digest" ~ '^[0-9a-f]{64}$' and "effect_digest" ~ '^[0-9a-f]{64}$' and "source_digest" ~ '^[0-9a-f]{64}$' and "witness_digest" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "access_group_approval_payload_check" CHECK (octet_length("proof"::text)<=1024 and octet_length("selection"::text)<=8192)
);

CREATE TABLE "access_recovery_path" (
	"id" uuid PRIMARY KEY,
	"scope_id" uuid NOT NULL,
	"principal_id" uuid NOT NULL,
	"subject_id" uuid NOT NULL,
	"proof" jsonb NOT NULL,
	"selection" jsonb NOT NULL,
	"source_digest" text NOT NULL,
	"request_digest" text NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"created_xid" text DEFAULT pg_current_xact_id() NOT NULL,
	"valid_until" timestamp(3) with time zone NOT NULL,
	"revoked_at" timestamp(3) with time zone,
	"revoke_operation_id" uuid,
	CONSTRAINT "access_recovery_path_xid_check" CHECK ("created_xid"::xid8>'0'::xid8),
	CONSTRAINT "access_recovery_path_time_check" CHECK (isfinite("valid_until") and "valid_until">"created_at" and ("revoked_at" is null)=("revoke_operation_id" is null)),
	CONSTRAINT "access_recovery_path_digest_check" CHECK ("source_digest" ~ '^[0-9a-f]{64}$' and "request_digest" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "access_recovery_path_payload_check" CHECK (octet_length("proof"::text)<=1024 and octet_length("selection"::text)<=8192)
);

CREATE TABLE "access_recovery_policy" (
	"scope_id" uuid PRIMARY KEY,
	"version" bigint DEFAULT 1 NOT NULL,
	"policy" text DEFAULT 'native-repair-v1' NOT NULL,
	CONSTRAINT "access_recovery_policy_check" CHECK ("version" between 1 and 9007199254740991 and "policy"='native-repair-v1')
);

CREATE UNIQUE INDEX "access_group_admission_review_key" ON "access_group_admission_receipt" ("review_id");
CREATE UNIQUE INDEX "access_group_approval_principal_key" ON "access_group_approval" ("review_id","principal_id");
CREATE INDEX "access_membership_active_scope_idx" ON "access_membership" ("scope_id","subject_id") WHERE "active_generation" is not null;
CREATE INDEX "access_recovery_path_scope_idx" ON "access_recovery_path" ("scope_id","valid_until","id") WHERE "revoked_at" is null;
CREATE INDEX "access_recovery_path_expiry_idx" ON "access_recovery_path" ("valid_until","id");
CREATE INDEX "access_representation_active_controller_idx" ON "access_representation" ("entity_id","id") WHERE "state"='active';
